	evidence.OwNew(words, 1, 0, 0, 10000, 10000, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1)
	evidence.OwNew(words, 1, 0, 0, 0, 100, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1)
