func oftWord(words *port.Cells, start int32, spanlen int32, run int32, conf int32, flags int32) int32 {
	var w int32 = evidence.OwNew(words, 1, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, start, spanlen, 0, conf, -1)
	evidence.OwSet(words, w, evidence.OwfRun(), run)
	evidence.OwSet(words, w, evidence.OwfFlags(), flags)
	return w
}

func oftRun(runs *port.Cells, first int32, count int32, pass int32) int32 {
	var r int32 = evidence.OrNew(runs, 1, 0)
	evidence.OrSet(runs, r, evidence.OrfPass(), pass)
	evidence.OrSet(runs, r, evidence.OrfWfirst(), first)
	evidence.OrSet(runs, r, evidence.OrfWcount(), count)
	return r
}

