func oftClose(runs *port.Cells, lines *port.Cells, pass int32, w0 int32, w1 int32, x1 int32, y1 int32) int32 {
	// Run `pass` of words [w0, w1), one line over all of them.
	var r int32 = evidence.OrNew(runs, 1, -1)
	var l int32 = evidence.OlNew(lines, 1, 1000, 1000, x1, y1, 1000, y1, x1, y1, 0, 0, w0, w1-w0)
	evidence.OlSet(lines, l, evidence.OlfRun(), r)
	evidence.OrSet(runs, r, evidence.OrfPass(), pass)
	evidence.OrSet(runs, r, evidence.OrfLfirst(), l)
	evidence.OrSet(runs, r, evidence.OrfLcount(), 1)
	evidence.OrSet(runs, r, evidence.OrfWfirst(), w0)
	evidence.OrSet(runs, r, evidence.OrfWcount(), w1-w0)
	return r
}

func oftReading(runs *port.Cells, lines *port.Cells, words *port.Cells, variant int32, pass int32, dx int32, conf int32, run int32, line int32) int32 {
	var w0 int32 = evidence.OwCount(words)
	var ts int32 = 0
	var cash int32 = 800
	if (variant & 8) != 0 {
		oftW(words, 1000+dx, 1000, 1500+dx, 1200, 19, 2, run, line, 950, 1)
	} else {
		oftW(words, 1000+dx, 1000, 1500+dx, 1200, 0, 5, run, line, 950, 1)
	}
	ts = 10
	if (variant & 2) != 0 {
		ts = 21
	}
	if (variant & 512) == 0 {
		oftW(words, 3000+dx, 1000, 3500+dx, 1200, ts, 5, run, line, conf, 2)
	} else {
		oftW(words, 7000+dx, 1000, 7260+dx, 1200, 21, 5, run, line, conf, 2)
	}
	if (variant & 64) != 0 {
		cash = 650
	}
	if (variant & 96) != 0 {
		oftW(words, 1000+dx, 3000, 1500+dx, 3200, 15, 4, run, line, cash, 1)
	}
	if (variant & 128) != 0 {
		oftW(words, 1600+dx, 1000, 2000+dx, 1200, 15, 4, run, line, cash, 1)
	}
	if (variant & 256) != 0 {
		oftW(words, 6000, 1000, 6500, 1200, 2147483647, 5, run, line, 990, 2)
	}
	return oftClose(runs, lines, pass, w0, evidence.OwCount(words), 7600, 3200)
}

func oftPage(runs *port.Cells, lines *port.Cells, words *port.Cells, text *port.Cells, scr *port.Cells, variant int32) int32 {
	// The page; answers the selection's count (1).
	var ts int32 = 5
	var k int32 = 0
	oftCps(text)
	if (variant & 8) != 0 {
		oftW(words, 1000, 1000, 1500, 1200, 19, 2, 0, 0, 950, 1)
	} else {
		oftW(words, 1000, 1000, 1500, 1200, 0, 5, 0, 0, 950, 1)
	}
	if (variant & 1) != 0 {
		ts = 10
	}
	if (variant & 512) == 0 {
		oftW(words, 3000, 1000, 3500, 1200, ts, 5, 0, 0, 400, 0)
	} else {
		for k < 5 {
			oftW(words, 7000+(k*40), 1000, 7100+(k*40), 1200, 19, 2, 0, 0, 400, 0)
			k += 1
		}
	}
	if (variant & 16) != 0 {
		oftW(words, 5000, 1000, 5300, 1200, 19, 2, 0, 0, 300, 0)
	}
	if (variant & 1024) != 0 {
		oftW(words, 5000, 1000, 5300, 1200, 19, 2, 0, 0, 200, 0)
	}
	oftClose(runs, lines, 1, 0, evidence.OwCount(words), 7600, 1200)
	if (variant & 4) == 0 {
		oftReading(runs, lines, words, variant, 6, 0, 900, 1, 1)
		oftReading(runs, lines, words, variant, 10, 20, 920, 2, 2)
	}
	scan.ScPrep(scr)
	port.CellsSet(scr, scan.ScXtraBase(), 0)
	port.CellsSet(scr, scan.ScXtraBase()+1, 0)
	port.CellsSet(scr, scan.ScSelBase(), 0)
	if (variant & 1024) != 0 {
		port.CellsSet(scr, scan.ScAdmitFloor(), 300)
	}
	return 1
}

func oftFuse(runs *port.Cells, lines *port.Cells, words *port.Cells, text *port.Cells, scr *port.Cells, ofz *port.Cells, image int32, trigger int32, r1 *port.Cells) int32 {
	return ofuse.OfFuse(1, image, trigger, runs, lines, words, text, port.NewCells(), scr, 1, ofz, r1, port.NewCells(), port.NewCells(), port.NewCells(), port.NewCells(), port.NewCells(), port.NewCells(), port.NewCells(), port.NewCells(), port.NewCells())
}

func oftZ(ofz *port.Cells, row int32, f int32) int32 {
	return port.CellsAt(ofz, (row*evidence.OzStride())+f)
}

func TestFusionReplacesAMalformedNumberWithAnAgreedVerbatimCopy(emonT *testing.T) {
	var runs *port.Cells = port.NewCells()
	var lines *port.Cells = port.NewCells()
	var words *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var scr *port.Cells = port.NewCells()
	var ofz *port.Cells = port.NewCells()
	oftPage(runs, lines, words, text, scr, 0)
	port.AssertEq(emonT, oftFuse(runs, lines, words, text, scr, ofz, 1, 1, port.NewCells()), 1, "one selected line")
	port.AssertEq(emonT, evidence.OrCount(runs), 4, "one synthetic run")
	port.AssertEq(emonT, evidence.OrGet(runs, 3, evidence.OrfPass()), evidence.OpFused(), "pass fused")
	port.AssertEq(emonT, port.CellsAt(scr, scan.ScSelBase()), 3, "the selection reads the fused line")
	port.AssertEq(emonT, evidence.OlGet(lines, 3, evidence.LhCount()), 2, "both words of the line")
	port.AssertEq(emonT, evidence.OlGet(lines, 3, evidence.LhFirst()), 6, "copies follow every recorded word")
	port.AssertEq(emonT, ofuse.OfSource(words, 6), 0, "TOTAL is a copy of the selected word")
	port.AssertEq(emonT, ofuse.OfSource(words, 7), 3, "12.00 is a copy of the earliest agreeing reading")
	port.AssertEq(emonT, evidence.OwGet(words, 7, evidence.HdTstart()), 10, "the copy's text is the recorded text")
	port.AssertEq(emonT, evidence.OwGet(words, 7, evidence.HdConf()), 900, "and its confidence")
	port.AssertEq(emonT, evidence.OwGet(words, 1, evidence.HdTstart()), 5, "the displaced word is unchanged evidence")
	port.AssertEq(emonT, evidence.OwGet(words, 1, evidence.OwfRun()), 0, "in its own run")
	port.AssertEq(emonT, port.CellsLen(ofz)/evidence.OzStride(), 2, "one row per considered slot")
	port.AssertEq(emonT, oftZ(ofz, 0, evidence.OzfRule()), 0, "TOTAL is kept")
	port.AssertEq(emonT, oftZ(ofz, 0, evidence.OzfOp()), 0, "keep")
	port.AssertEq(emonT, oftZ(ofz, 0, evidence.OzfIvotes()), 3, "every reading agrees with it")
	port.AssertEq(emonT, oftZ(ofz, 0, evidence.OzfCcount()), 0, "nothing chosen")
	port.AssertEq(emonT, oftZ(ofz, 1, evidence.OzfRule()), 1, "agreement")
	port.AssertEq(emonT, oftZ(ofz, 1, evidence.OzfOp()), 1, "replace")
	port.AssertEq(emonT, oftZ(ofz, 1, evidence.OzfIfirst()), 1, "the selected word")
	port.AssertEq(emonT, oftZ(ofz, 1, evidence.OzfIcount()), 1, "one selected word")
	port.AssertEq(emonT, oftZ(ofz, 1, evidence.OzfCfirst()), 7, "the copy")
	port.AssertEq(emonT, oftZ(ofz, 1, evidence.OzfCcount()), 1, "one copied word")
	port.AssertEq(emonT, oftZ(ofz, 1, evidence.OzfVotes()), 2, "two readings")
	port.AssertEq(emonT, oftZ(ofz, 1, evidence.OzfIvotes()), 1, "against one")
	port.AssertEq(emonT, oftZ(ofz, 1, evidence.OzfNulls()), 0, "no silent full reading")
	port.AssertEq(emonT, oftZ(ofz, 1, evidence.OzfMargin()), 520, "920 against 400")
	port.AssertEq(emonT, oftZ(ofz, 1, evidence.OzfReadings()), 7, "all three readings")
}

