func oftSame(emonT *testing.T, a *port.Cells, b *port.Cells) int32 {
	var i int32 = 0
	port.AssertEq(emonT, port.CellsLen(a), port.CellsLen(b), "same length")
	for (i < port.CellsLen(a)) && (i < port.CellsLen(b)) {
		port.AssertEq(emonT, port.CellsAt(a, i), port.CellsAt(b, i), "same cell")
		i += 1
	}
	return 0
}

